package main

import (
	"bufio"
	"crypto/tls"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
)

const version = "dev"

// Exit codes
const (
	exitOK             = 0
	exitOpenFile       = 1
	exitReadInput      = 2
	exitFormStatements = 3
	exitFetchURL       = 4
	exitParseStatements = 5
	exitJSONEncode     = 6
)

type options struct {
	ungron      bool
	values      bool
	colorize    bool
	monochrome  bool
	stream      bool
	insecure    bool
	jsonMode    bool
	noSort      bool
	noProxy     string
	proxy       string
	version     bool
}

var usage = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
