package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenType int

const (
	TypeBare tokenType = iota
	TypeDot
	TypeEquals
	TypeLBrace   // {
	TypeRBrace   // }
	TypeLBracket // [
	TypeRBracket // ]
	TypeSemi
	TypeNumber
	TypeString // quoted string, includes quotes
	TypeBool
	TypeNull
	TypeQuotedKey // "key" as in json["key"] (has surrounding quotes)
)

type token struct {
	typ  tokenType
	text string
}

type statement []token

type statements []statement

// buildStatements walks v and appends statements based on prefix
func buildStatements(out statements, prefix statement, v interface{}) statements {
	// First, emit the statement for prefix = value
	switch val := v.(type) {
	case map[string]interface{}:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeLBrace, "{"})
		s = append(s, token{TypeRBrace, "}"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
		for k, child := range val {
			childPrefix := appendKey(prefix, k)
			out = buildStatements(out, childPrefix, child)
		}
	case []interface{}:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeLBracket, "["})
		s = append(s, token{TypeRBracket, "]"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
		for i, child := range val {
			childPrefix := appendIndex(prefix, i)
			out = buildStatements(out, childPrefix, child)
		}
	case nil:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeNull, "null"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case bool:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		if val {
			s = append(s, token{TypeBool, "true"})
		} else {
			s = append(s, token{TypeBool, "false"})
		}
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case json.Number:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeNumber, string(val)})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case string:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeString, encodeString(val)})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	default:
		// Fallback: serialize via json
		raw, _ := json.Marshal(val)
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
