// stmtLess compares two statements by their key path semantics
func stmtLess(a, b statement) bool {
	ai, bi := 0, 0
	// Skip over path comparisons; stop at TypeEquals
	for ai < len(a) && bi < len(b) {
		at := a[ai]
		bt := b[bi]
		if at.typ == TypeEquals || bt.typ == TypeEquals {
			// Shorter path first
			if at.typ == TypeEquals && bt.typ == TypeEquals {
				return false
			}
			return at.typ == TypeEquals
		}
		// Compare token by token
		if at.typ == TypeDot && bt.typ == TypeDot {
			ai++
			bi++
			continue
		}
		if at.typ == TypeDot && bt.typ == TypeLBracket {
			// bare comes after bracket? Let's test...
			// From testing: json.active before json["123"] — so bare identifier (.active) < bracketed ("123") when bracket content is string
			// And json.a before json[""] — dot < bracket for same parent?
			// So dot comes before bracket
			return true
		}
		if at.typ == TypeLBracket && bt.typ == TypeDot {
			return false
		}
		if at.typ == TypeBare && bt.typ == TypeBare {
			if at.text != bt.text {
				return at.text < bt.text
			}
			ai++
			bi++
			continue
		}
		if at.typ == TypeLBracket && bt.typ == TypeLBracket {
			// Compare next token
			an := a[ai+1]
			bn := b[bi+1]
			if an.typ == TypeNumber && bn.typ == TypeNumber {
				av, _ := strconv.Atoi(an.text)
				bv, _ := strconv.Atoi(bn.text)
				if av != bv {
					return av < bv
				}
				ai += 3
				bi += 3
				continue
			}
			if an.typ == TypeNumber && bn.typ == TypeQuotedKey {
				// numbers before quoted keys?
				return true
			}
			if an.typ == TypeQuotedKey && bn.typ == TypeNumber {
				return false
			}
			if an.typ == TypeQuotedKey && bn.typ == TypeQuotedKey {
				if an.text != bn.text {
					return an.text < bn.text
				}
				ai += 3
				bi += 3
				continue
			}
		}
		// Fallback: compare as strings
		if at.text != bt.text {
			return at.text < bt.text
		}
		ai++
		bi++
	}
	return len(a) < len(b)
}
