	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			// Invalid UTF-8, write replacement
			sb.WriteRune(utf8.RuneError)
			i += size
			continue
		}
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		case '\u2028':
			sb.WriteString(`\u2028`)
		case '\u2029':
			sb.WriteString(`\u2029`)
		default:
			if r < 0x20 || (r >= 0x7F && r <= 0x9F) {
				sb.WriteString(fmt.Sprintf("\\u%04X", r))
			} else {
				sb.WriteRune(r)
			}
		}
		i += size
	}
	sb.WriteByte('"')
	return sb.String()
}

// formatStatement formats the statement as a string
func formatStatement(s statement, colorize bool) string {
	var sb strings.Builder
	lastWasBare := false
	for _, t := range s {
		switch t.typ {
		case TypeBare:
			if colorize {
				sb.WriteString("\033[34;1m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0;22m")
			} else {
				sb.WriteString(t.text)
			}
			lastWasBare = true
		case TypeDot:
			sb.WriteString(".")
			lastWasBare = false
		case TypeEquals:
			sb.WriteString(" = ")
			lastWasBare = false
		case TypeLBrace:
			if colorize {
				sb.WriteString("\033[35m{")
			} else {
				sb.WriteString("{")
			}
			lastWasBare = false
		case TypeRBrace:
			if colorize {
				sb.WriteString("}\033[0m")
			} else {
				sb.WriteString("}")
			}
			lastWasBare = false
		case TypeLBracket:
			if colorize {
				sb.WriteString("\033[35m[\033[0m")
			} else {
				sb.WriteString("[")
			}
			lastWasBare = false
		case TypeRBracket:
			if colorize {
				sb.WriteString("\033[35m]\033[0m")
			} else {
				sb.WriteString("]")
			}
			lastWasBare = false
		case TypeSemi:
			sb.WriteString(";")
		case TypeNumber:
			if colorize {
				sb.WriteString("\033[31m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
			}
		case TypeString:
			if colorize {
				sb.WriteString("\033[33m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
			}
		case TypeQuotedKey:
			if colorize {
				sb.WriteString("\033[33m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
			}
		case TypeBool, TypeNull:
			if colorize {
				sb.WriteString("\033[36m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
			}
		}
		_ = lastWasBare
	}
	return sb.String()
}

// statementToJSON produces the JSON array form [path, value]
func statementToJSON(s statement, colorize bool) (string, error) {
	// Extract path tokens and value token
	var path []interface{}
	var value interface{} = nil
	var valueSet = false
	var afterEquals = false
	i := 0
	for i < len(s) {
		t := s[i]
		if t.typ == TypeEquals {
			afterEquals = true
			i++
			continue
		}
		if !afterEquals {
			switch t.typ {
			case TypeBare:
				if t.text != "json" {
					path = append(path, t.text)
				}
			case TypeDot:
				// skip
			case TypeLBracket:
				// look for index or key
				if i+2 < len(s) && s[i+1].typ == TypeNumber && s[i+2].typ == TypeRBracket {
					n, _ := strconv.Atoi(s[i+1].text)
					path = append(path, n)
					i += 2
				} else if i+2 < len(s) && s[i+1].typ == TypeQuotedKey && s[i+2].typ == TypeRBracket {
					// decode quoted string
					raw := s[i+1].text
					var str string
					if err := json.Unmarshal([]byte(raw), &str); err == nil {
						path = append(path, str)
					}
					i += 2
				}
			}
		} else {
			// value
			switch t.typ {
			case TypeLBrace:
				if i+1 < len(s) && s[i+1].typ == TypeRBrace {
					value = map[string]interface{}{}
					valueSet = true
					i++
				}
			case TypeLBracket:
				if i+1 < len(s) && s[i+1].typ == TypeRBracket {
					value = []interface{}{}
					valueSet = true
					i++
				}
			case TypeNumber:
				value = json.Number(t.text)
				valueSet = true
			case TypeString:
				// decode
				var str string
				if err := json.Unmarshal([]byte(t.text), &str); err == nil {
					value = str
				}
				valueSet = true
			case TypeBool:
				value = t.text == "true"
				valueSet = true
			case TypeNull:
				value = nil
				valueSet = true
			}
		}
		i++
	}
	_ = valueSet

	// Marshal [path, value]
	arr := []interface{}{path, value}
	if path == nil {
		arr[0] = []interface{}{}
	}
	data, err := marshalJSONNoEscape(arr)
	if err != nil {
		return "", err
	}
	return data, nil
}

func marshalJSONNoEscape(v interface{}) (string, error) {
	var sb strings.Builder
	enc := json.NewEncoder(&sb)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return "", err
	}
	out := sb.String()
	out = strings.TrimRight(out, "\n")
	return out, nil
}

// sort sorts the statements
func (ss statements) sort() {
	sort.Slice(ss, func(i, j int) bool {
		return stmtLess(ss[i], ss[j])
	})
}

// stmtLess compares two statements by their key path semantics
func stmtLess(a, b statement) bool {
	ai, bi := 0, 0
	// Skip over path comparisons; stop at TypeEquals
	for ai < len(a) && bi < len(b) {
		at := a[ai]
		bt := b[bi]
		if at.typ == TypeEquals || bt.typ == TypeEquals {
			// Shorter path first
			if at.typ == TypeEquals && bt.typ == TypeEquals {
				return false
			}
			return at.typ == TypeEquals
		}
		// Compare token by token
		if at.typ == TypeDot && bt.typ == TypeDot {
			ai++
			bi++
			continue
		}
		if at.typ == TypeDot && bt.typ == TypeLBracket {
			// bare comes after bracket? Let's test...
			// From testing: json.active before json["123"] — so bare identifier (.active) < bracketed ("123") when bracket content is string
			// And json.a before json[""] — dot < bracket for same parent?
			// So dot comes before bracket
			return true
		}
		if at.typ == TypeLBracket && bt.typ == TypeDot {
			return false
		}
		if at.typ == TypeBare && bt.typ == TypeBare {
			if at.text != bt.text {
				return at.text < bt.text
			}
			ai++
			bi++
			continue
		}
		if at.typ == TypeLBracket && bt.typ == TypeLBracket {
			// Compare next token
			an := a[ai+1]
			bn := b[bi+1]
			if an.typ == TypeNumber && bn.typ == TypeNumber {
				av, _ := strconv.Atoi(an.text)
				bv, _ := strconv.Atoi(bn.text)
				if av != bv {
					return av < bv
				}
				ai += 3
				bi += 3
				continue
			}
			if an.typ == TypeNumber && bn.typ == TypeQuotedKey {
				// numbers before quoted keys?
				return true
			}
			if an.typ == TypeQuotedKey && bn.typ == TypeNumber {
				return false
			}
			if an.typ == TypeQuotedKey && bn.typ == TypeQuotedKey {
				if an.text != bn.text {
					return an.text < bn.text
				}
				ai += 3
				bi += 3
				continue
			}
		}
		// Fallback: compare as strings
		if at.text != bt.text {
			return at.text < bt.text
		}
		ai++
		bi++
	}
	return len(a) < len(b)
}
