// parseGronLine parses a line like `json.a.b[0] = "value";` and returns
// the path (as []interface{}) and the value
func parseGronLine(line string) ([]interface{}, interface{}, error) {
	trimmed := strings.TrimSpace(line)
	// Validate: must be `[path] = value;` structure

	// Lex the line
	l := newLexer(line)
	tokens, err := l.lexStatement()
	if err != nil {
		prefix := l.errorPrefix()
		return nil, nil, fmt.Errorf("ungron failed for `%s`: %s", prefix, err.Error())
	}
	// tokens: path tokens, then equals, then value token
	eqIdx := -1
	for i, t := range tokens {
		if t.typ == TypeEquals {
			eqIdx = i
			break
		}
	}
	if eqIdx == -1 {
		return nil, nil, fmt.Errorf("ungron failed for `%s`: invalid statement", trimmed)
	}
	pathToks := tokens[:eqIdx]
	valToks := tokens[eqIdx+1:]

	path, err := pathTokensToPath(pathToks)
	if err != nil {
		return nil, nil, fmt.Errorf("ungron failed for `%s`: %s", trimmed, err.Error())
	}

	// Extract value: expect single value token (optionally followed by ;)
	value, err := extractValueFromTokens(valToks)
	if err != nil {
		return nil, nil, fmt.Errorf("ungron failed for `%s`: %s", strings.TrimRight(l.consumed, " \t"), err.Error())
	}
	return path, value, nil
}

// parseJSONLine parses a JSON stream line `[path_array, value]`
func parseJSONLine(line string) ([]interface{}, interface{}, error) {
	var arr []interface{}
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	if err := dec.Decode(&arr); err != nil {
		return nil, nil, err
	}
	if len(arr) != 2 {
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	pathRaw, ok := arr[0].([]interface{})
	if !ok {
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	// Validate path elements
	path := make([]interface{}, 0, len(pathRaw))
	for _, p := range pathRaw {
		switch pv := p.(type) {
		case string:
			path = append(path, pv)
		case json.Number:
			n, err := pv.Int64()
			if err != nil {
				return nil, nil, fmt.Errorf("invalid JSON layout")
			}
			path = append(path, int(n))
		default:
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	}
	// Validate value
	value := arr[1]
	switch v := value.(type) {
	case nil, bool, string, json.Number:
		// ok
	case map[string]interface{}:
		if len(v) != 0 {
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	case []interface{}:
		if len(v) != 0 {
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	default:
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	return path, value, nil
}

// pathTokensToPath converts a sequence of path tokens to a slice of keys/indices
func pathTokensToPath(toks []token) ([]interface{}, error) {
	var result []interface{}
	i := 0
	for i < len(toks) {
		t := toks[i]
		switch t.typ {
		case TypeBare:
			result = append(result, t.text)
			i++
		case TypeDot:
			i++
			if i >= len(toks) || toks[i].typ != TypeBare {
				return nil, fmt.Errorf("invalid statement")
			}
			result = append(result, toks[i].text)
			i++
		case TypeLBracket:
			i++
			if i >= len(toks) {
				return nil, fmt.Errorf("invalid statement")
			}
			switch toks[i].typ {
			case TypeNumber:
				n, err := strconv.Atoi(toks[i].text)
				if err != nil {
					return nil, fmt.Errorf("invalid statement")
				}
				result = append(result, n)
			case TypeQuotedKey:
				// decode the JSON string
				var s string
				if err := json.Unmarshal([]byte(toks[i].text), &s); err != nil {
					return nil, fmt.Errorf("invalid statement")
				}
				result = append(result, s)
			default:
				return nil, fmt.Errorf("invalid statement")
			}
			i++
			if i >= len(toks) || toks[i].typ != TypeRBracket {
				return nil, fmt.Errorf("invalid statement")
			}
			i++
		default:
			return nil, fmt.Errorf("invalid statement")
		}
	}
	return result, nil
}

// extractValueFromTokens takes tokens after the `=` and returns the value
func extractValueFromTokens(toks []token) (interface{}, error) {
	if len(toks) == 0 {
		return nil, fmt.Errorf("statement has no value")
	}
	// Possible token sequences:
	//   [number, ;]  [string, ;] [bool, ;] [null, ;]
	//   [{, }, ;]    [[, ], ;]
	t := toks[0]
	switch t.typ {
	case TypeNumber:
		return json.Number(t.text), nil
	case TypeString:
		var s string
		if err := json.Unmarshal([]byte(t.text), &s); err != nil {
			return nil, fmt.Errorf("invalid value `%s`", t.text)
		}
		return s, nil
	case TypeBool:
		return t.text == "true", nil
	case TypeNull:
		return nil, nil
	case TypeLBrace:
		if len(toks) >= 2 && toks[1].typ == TypeRBrace {
			return map[string]interface{}{}, nil
		}
		return nil, fmt.Errorf("statement has no value")
	case TypeLBracket:
		if len(toks) >= 2 && toks[1].typ == TypeRBracket {
			return []interface{}{}, nil
		}
		return nil, fmt.Errorf("statement has no value")
	case TypeSemi:
		return nil, fmt.Errorf("invalid value ``")
	default:
		return nil, fmt.Errorf("invalid value `%s`", t.text)
	}
}

// mergePath merges a value at the given path into the root
func mergePath(root interface{}, path []interface{}, value interface{}) (interface{}, error) {
	return mergeInto(root, path, value)
}

func mergeInto(root interface{}, path []interface{}, value interface{}) (interface{}, error) {
	if len(path) == 0 {
		return value, nil
	}
	key := path[0]
	rest := path[1:]
	switch k := key.(type) {
	case int:
		// expect root to be []interface{} or nil
		var arr []interface{}
		if root == nil {
			arr = []interface{}{}
		} else {
			var ok bool
			arr, ok = root.([]interface{})
			if !ok {
				return nil, fmt.Errorf("failed to merge statements: cannot merge array with non-array")
			}
		}
		for len(arr) <= k {
			arr = append(arr, nil)
		}
		nested, err := mergeInto(arr[k], rest, value)
		if err != nil {
			return nil, err
		}
		arr[k] = nested
		return arr, nil
	case string:
		var obj map[string]interface{}
		if root == nil {
			obj = map[string]interface{}{}
		} else {
			var ok bool
			obj, ok = root.(map[string]interface{})
			if !ok {
				return nil, fmt.Errorf("failed to merge statements: cannot merge object with non-object")
			}
		}
		nested, err := mergeInto(obj[k], rest, value)
		if err != nil {
			return nil, err
		}
		obj[k] = nested
		return obj, nil
	}
	return root, nil
}

// encodeJSON pretty-prints the value as JSON
func encodeJSON(v interface{}, colorize bool) (string, error) {
	if colorize {
		return encodeJSONColor(v)
	}
	var sb strings.Builder
	enc := json.NewEncoder(&sb)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return "", err
	}
	out := sb.String()
	out = strings.TrimRight(out, "\n")
	return out, nil
}

// encodeJSONColor produces colored JSON (compressed)
func encodeJSONColor(v interface{}) (string, error) {
	var sb strings.Builder
	err := writeColorValue(&sb, v, false)
	return sb.String(), err
}

func writeColorValue(sb *strings.Builder, v interface{}, isKey bool) error {
	switch val := v.(type) {
	case map[string]interface{}:
		sb.WriteString("\033[35m{\033[0m")
		// Sort keys
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		// Sort in stable order
		// Using simple lex sort
		for i := 1; i < len(keys); i++ {
			for j := i; j > 0 && keys[j-1] > keys[j]; j-- {
				keys[j-1], keys[j] = keys[j], keys[j-1]
			}
		}
		for i, k := range keys {
			if i > 0 {
				sb.WriteString("\033[1m,\033[22m")
			}
			// Write key with bold blue
			sb.WriteString("\033[34;1m\"\033[0;22m")
			sb.WriteString("\033[34;1m")
			writeEscapedStringInner(sb, k)
			sb.WriteString("\033[0;22m")
			sb.WriteString("\033[34;1m\"\033[0;22m")
			sb.WriteString("\033[1m:\033[22m")
			if err := writeColorValue(sb, val[k], false); err != nil {
				return err
			}
		}
		sb.WriteString("\033[35m}\033[0m")
	case []interface{}:
		sb.WriteString("\033[35m[\033[0m")
		for i, item := range val {
			if i > 0 {
				sb.WriteString("\033[1m,\033[22m")
			}
			if err := writeColorValue(sb, item, false); err != nil {
				return err
			}
		}
		sb.WriteString("\033[35m]\033[0m")
	case nil:
		sb.WriteString("\033[36mnull\033[0m")
	case bool:
		if val {
			sb.WriteString("\033[36mtrue\033[0m")
		} else {
			sb.WriteString("\033[36mfalse\033[0m")
		}
	case json.Number:
		sb.WriteString("\033[31m")
		sb.WriteString(string(val))
		sb.WriteString("\033[0m")
	case string:
		sb.WriteString("\033[32m\"\033[0m")
		sb.WriteString("\033[33m")
		writeEscapedStringInner(sb, val)
		sb.WriteString("\033[0m")
		sb.WriteString("\033[32m\"\033[0m")
	default:
		// fallback via json marshal
		b, err := json.Marshal(v)
		if err != nil {
			return err
		}
		sb.WriteString(string(b))
	}
	return nil
}

func writeEscapedStringInner(sb *strings.Builder, s string) {
	// Use gron's string encoding (without outer quotes)
	encoded := encodeString(s)
	// Strip outer quotes
	if len(encoded) >= 2 {
		sb.WriteString(encoded[1 : len(encoded)-1])
	}
}

// --- Lexer ---

type lexer struct {
	input    string
	pos      int
	consumed string // prefix of input consumed so far
}

func newLexer(s string) *lexer {
	return &lexer{input: s}
}

// errorPrefix returns the input consumed so far (for error messages)
func (l *lexer) errorPrefix() string {
	// Return input up to current position, minus trailing whitespace
	s := l.input[:l.pos]
	return strings.TrimRight(s, " \t")
}

func (l *lexer) lexStatement() ([]token, error) {
	var tokens []token
	// Strip possible trailing whitespace
	// Parse path tokens until `=`
	// Path tokens: identifier, .ident, [number], ["string"]
	// Then value: string, number, true/false/null, {}, []

	// Optional initial whitespace? Actually, from tests, leading whitespace breaks parsing.
	seenEquals := false
	afterEquals := false
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if !seenEquals {
			if c == ' ' || c == '\t' {
				// whitespace only allowed around `=`
				// skip single space before `=`
				l.pos++
				continue
			}
			if c == '.' {
				tokens = append(tokens, token{TypeDot, "."})
				l.pos++
				// Read identifier
				ident, err := l.lexIdent()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeBare, ident})
				continue
			}
			if c == '[' {
				tokens = append(tokens, token{TypeLBracket, "["})
				l.pos++
				// Read either number or "quoted string"
				if l.pos >= len(l.input) {
					return nil, fmt.Errorf("invalid statement")
				}
				nc := l.input[l.pos]
				if nc == '"' {
					q, err := l.lexQuoted()
					if err != nil {
						return nil, err
					}
					tokens = append(tokens, token{TypeQuotedKey, q})
				} else if nc == '-' || (nc >= '0' && nc <= '9') {
					n, err := l.lexNumber()
					if err != nil {
						return nil, err
					}
					tokens = append(tokens, token{TypeNumber, n})
				} else {
					return nil, fmt.Errorf("invalid statement")
				}
				// expect closing ]
				if l.pos >= len(l.input) || l.input[l.pos] != ']' {
					return nil, fmt.Errorf("invalid statement")
				}
				tokens = append(tokens, token{TypeRBracket, "]"})
				l.pos++
				continue
			}
			if c == '=' {
				tokens = append(tokens, token{TypeEquals, "="})
				l.pos++
				seenEquals = true
				afterEquals = true
				continue
			}
			if isIdentStart(rune(c)) {
				// Identifier
				ident, err := l.lexIdent()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeBare, ident})
				continue
			}
			return nil, fmt.Errorf("invalid statement")
		} else if afterEquals {
			if c == ' ' || c == '\t' {
				l.pos++
				continue
			}
			if c == '"' {
				q, err := l.lexQuoted()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeString, q})
				afterEquals = false
				continue
			}
			if c == '-' || (c >= '0' && c <= '9') {
				n, err := l.lexNumber()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeNumber, n})
				afterEquals = false
				continue
			}
			if c == '{' {
				tokens = append(tokens, token{TypeLBrace, "{"})
				l.pos++
				// expect } immediately (possibly after whitespace?)
				if l.pos < len(l.input) && l.input[l.pos] == '}' {
					tokens = append(tokens, token{TypeRBrace, "}"})
					l.pos++
					afterEquals = false
					continue
				}
				return nil, fmt.Errorf("statement has no value")
			}
			if c == '[' {
				tokens = append(tokens, token{TypeLBracket, "["})
				l.pos++
				if l.pos < len(l.input) && l.input[l.pos] == ']' {
					tokens = append(tokens, token{TypeRBracket, "]"})
					l.pos++
					afterEquals = false
					continue
				}
				return nil, fmt.Errorf("statement has no value")
			}
			// try literals true, false, null
			if strings.HasPrefix(l.input[l.pos:], "true") {
				tokens = append(tokens, token{TypeBool, "true"})
				l.pos += 4
				afterEquals = false
				continue
			}
			if strings.HasPrefix(l.input[l.pos:], "false") {
				tokens = append(tokens, token{TypeBool, "false"})
				l.pos += 5
				afterEquals = false
				continue
			}
			if strings.HasPrefix(l.input[l.pos:], "null") {
				tokens = append(tokens, token{TypeNull, "null"})
				l.pos += 4
				afterEquals = false
				continue
			}
			if c == ';' {
				return nil, fmt.Errorf("invalid value ``")
			}
			return nil, fmt.Errorf("invalid value `%c`", c)
		} else {
			// After value, expect ;, then end or ignore rest
			if c == ' ' || c == '\t' {
				l.pos++
				continue
			}
			if c == ';' {
				l.pos++
				// Ignore rest of line
				break
			}
			// ignore rest?
			break
		}
	}
	l.consumed = l.input[:l.pos]
	return tokens, nil
}

func (l *lexer) lexIdent() (string, error) {
	start := l.pos
	if l.pos >= len(l.input) {
		return "", fmt.Errorf("invalid statement")
	}
	r, size := utf8.DecodeRuneInString(l.input[l.pos:])
	if !isIdentStart(r) {
		return "", fmt.Errorf("invalid statement")
	}
	l.pos += size
	for l.pos < len(l.input) {
		r, size := utf8.DecodeRuneInString(l.input[l.pos:])
		if !isIdentPart(r) {
			break
		}
		l.pos += size
	}
	return l.input[start:l.pos], nil
}

func isIdentStart(r rune) bool {
	return unicode.IsLetter(r) || r == '$' || r == '_'
}

func isIdentPart(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '$' || r == '_'
}

func (l *lexer) lexQuoted() (string, error) {
	start := l.pos
	if l.pos >= len(l.input) || l.input[l.pos] != '"' {
		return "", fmt.Errorf("invalid statement")
	}
	l.pos++
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if c == '"' {
			l.pos++
			return l.input[start:l.pos], nil
		}
		if c == '\\' {
			l.pos++
			if l.pos >= len(l.input) {
				return "", fmt.Errorf("invalid statement")
			}
			l.pos++
			continue
		}
		l.pos++
	}
	return "", fmt.Errorf("invalid statement")
}

func (l *lexer) lexNumber() (string, error) {
	start := l.pos
	if l.pos < len(l.input) && l.input[l.pos] == '-' {
		l.pos++
	}
	hasDigit := false
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if c >= '0' && c <= '9' {
			l.pos++
			hasDigit = true
			continue
		}
		break
	}
	// optional fraction
	if l.pos < len(l.input) && l.input[l.pos] == '.' {
		l.pos++
		for l.pos < len(l.input) {
			c := l.input[l.pos]
			if c >= '0' && c <= '9' {
				l.pos++
				hasDigit = true
				continue
			}
			break
		}
	}
	// optional exponent
	if l.pos < len(l.input) && (l.input[l.pos] == 'e' || l.input[l.pos] == 'E') {
		l.pos++
		if l.pos < len(l.input) && (l.input[l.pos] == '+' || l.input[l.pos] == '-') {
			l.pos++
		}
		for l.pos < len(l.input) {
			c := l.input[l.pos]
			if c >= '0' && c <= '9' {
				l.pos++
				continue
			}
			break
		}
	}
	if !hasDigit {
		return "", fmt.Errorf("invalid statement")
	}
	return l.input[start:l.pos], nil
}

// --- Values extraction ---

func extractValue(line string) (string, bool, error) {
	l := newLexer(line)
	tokens, err := l.lexStatement()
	if err != nil {
		// Check if line is entirely whitespace -> error
		if strings.TrimSpace(line) == "" {
			return "", false, fmt.Errorf("failed to parse '%s' as gron statement", line)
		}
		// Otherwise, silently skip
		return "", false, nil
	}
	// Find value tokens
	eqIdx := -1
	for i, t := range tokens {
		if t.typ == TypeEquals {
			eqIdx = i
			break
		}
	}
	if eqIdx == -1 {
		return "", false, nil
	}
	valToks := tokens[eqIdx+1:]
	if len(valToks) == 0 {
		return "", true, nil
	}
	t := valToks[0]
	switch t.typ {
	case TypeString:
		var s string
		if err := json.Unmarshal([]byte(t.text), &s); err != nil {
			return t.text, true, nil
		}
		return s, true, nil
	case TypeNumber, TypeBool, TypeNull:
		return t.text, true, nil
	case TypeLBrace, TypeLBracket:
		// skip empty obj/arr
		return "", false, nil
	default:
		return t.text, true, nil
	}
}
