				sb.WriteString(t.text)
				sb.WriteString("\033[0;22m")
			} else {
				sb.WriteString(t.text)
			}
		case TypeDot:
			sb.WriteString(".")
		case TypeEquals:
			sb.WriteString(" = ")
		case TypeLBrace:
			if colorize {
				sb.WriteString("\033[35m{\033[0m")
			} else {
				sb.WriteString("{")
			}
