			if colorize {
				sb.WriteString("\033[31m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
			}
		case TypeString, TypeQuotedKey:
			if colorize {
				sb.WriteString("\033[33m")
				sb.WriteString(t.text)
				sb.WriteString("\033[0m")
			} else {
				sb.WriteString(t.text)
