	"fmt"
	"io"
	"strings"
)

// orderedMap preserves key insertion order
type orderedMap struct {
	keys []string
	vals map[string]interface{}
}

func newOrderedMap() *orderedMap {
	return &orderedMap{vals: map[string]interface{}{}}
}

func (m *orderedMap) set(k string, v interface{}) {
	if _, ok := m.vals[k]; !ok {
		m.keys = append(m.keys, k)
	}
	m.vals[k] = v
}

// decodeJSON parses the JSON in a stream manner, preserving key order.
func decodeJSON(r io.Reader) (interface{}, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return decodeValue(dec, tok)
}

func decodeValue(dec *json.Decoder, tok json.Token) (interface{}, error) {
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			m := newOrderedMap()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				valTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := decodeValue(dec, valTok)
				if err != nil {
					return nil, err
				}
				m.set(key, val)
			}
			// Consume closing brace
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return m, nil
		case '[':
			var arr []interface{}
			for dec.More() {
				valTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				val, err := decodeValue(dec, valTok)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			if arr == nil {
				arr = []interface{}{}
			}
			return arr, nil
		}
	}
	return tok, nil
}

// decodeStream decodes a sequence of JSON values from r
func decodeStream(r io.Reader) ([]interface{}, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	var values []interface{}
	for {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				return values, nil
			}
			return values, err
		}
		val, err := decodeValue(dec, tok)
		if err != nil {
			return values, err
		}
		values = append(values, val)
	}
}

