package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokenType int

const (
	TypeBare tokenType = iota
	TypeDot
	TypeEquals
	TypeLBrace
	TypeRBrace
	TypeLBracket
	TypeRBracket
	TypeSemi
	TypeNumber
	TypeString
	TypeBool
	TypeNull
	TypeQuotedKey
)

type token struct {
	typ  tokenType
	text string
}

type statement []token

type statements []statement

// Reserved JS keywords that cannot be bare identifiers
var reservedWords = map[string]bool{
	"break":      true,
	"case":       true,
	"catch":      true,
	"class":      true,
	"const":      true,
	"continue":   true,
	"debugger":   true,
	"default":    true,
	"delete":     true,
	"do":         true,
	"else":       true,
	"export":     true,
	"extends":    true,
	"false":      true,
	"finally":    true,
	"for":        true,
	"function":   true,
	"if":         true,
	"import":     true,
	"in":         true,
	"instanceof": true,
	"new":        true,
	"null":       true,
	"return":     true,
	"super":      true,
	"switch":     true,
	"this":       true,
	"throw":      true,
	"true":       true,
	"try":        true,
	"typeof":     true,
	"var":        true,
	"void":       true,
	"while":      true,
	"with":       true,
	"yield":      true,
}

func isValidBareIdentifier(s string) bool {
	if s == "" {
		return false
	}
	if reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !(unicode.IsLetter(r) || r == '$' || r == '_') {
				return false
			}
		} else {
			if !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '$' || r == '_') {
				return false
			}
		}
	}
	return true
}

// encodeString encodes s as a JSON string with gron's specific escaping rules
