// buildStatements walks v and appends statements based on prefix.
// Supports orderedMap, []interface{}, json.Number, etc.
func buildStatements(out statements, prefix statement, v interface{}) statements {
	switch val := v.(type) {
	case *orderedMap:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeLBrace, "{"})
		s = append(s, token{TypeRBrace, "}"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
		for _, k := range val.keys {
			childPrefix := appendKey(prefix, k)
			out = buildStatements(out, childPrefix, val.vals[k])
		}
	case map[string]interface{}:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeLBrace, "{"})
		s = append(s, token{TypeRBrace, "}"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
		for k, child := range val {
			childPrefix := appendKey(prefix, k)
			out = buildStatements(out, childPrefix, child)
		}
	case []interface{}:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeLBracket, "["})
		s = append(s, token{TypeRBracket, "]"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
		for i, child := range val {
			childPrefix := appendIndex(prefix, i)
			out = buildStatements(out, childPrefix, child)
		}
	case nil:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeNull, "null"})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case bool:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		if val {
			s = append(s, token{TypeBool, "true"})
		} else {
			s = append(s, token{TypeBool, "false"})
		}
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case json.Number:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeNumber, string(val)})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	case string:
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeString, encodeString(val)})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	default:
		raw, _ := json.Marshal(val)
		s := append(statement{}, prefix...)
		s = append(s, token{TypeEquals, "="})
		s = append(s, token{TypeString, string(raw)})
		s = append(s, token{TypeSemi, ";"})
		out = append(out, s)
	}
	return out
}

func appendKey(prefix statement, k string) statement {
	newPrefix := append(statement{}, prefix...)
	if isValidBareIdentifier(k) {
		newPrefix = append(newPrefix, token{TypeDot, "."})
		newPrefix = append(newPrefix, token{TypeBare, k})
	} else {
		newPrefix = append(newPrefix, token{TypeLBracket, "["})
		newPrefix = append(newPrefix, token{TypeQuotedKey, encodeString(k)})
		newPrefix = append(newPrefix, token{TypeRBracket, "]"})
	}
	return newPrefix
}

func appendIndex(prefix statement, i int) statement {
	newPrefix := append(statement{}, prefix...)
	newPrefix = append(newPrefix, token{TypeLBracket, "["})
	newPrefix = append(newPrefix, token{TypeNumber, strconv.Itoa(i)})
	newPrefix = append(newPrefix, token{TypeRBracket, "]"})
	return newPrefix
}

