package main

import "fmt"

// mergePath merges value at the given path into root
func mergePath(root interface{}, path []interface{}, value interface{}) (interface{}, error) {
	return mergeInto(root, path, value)
}

func mergeInto(root interface{}, path []interface{}, value interface{}) (interface{}, error) {
	if len(path) == 0 {
		// Replace root with value, but validate:
		// If root is a container and value is not the same-type container, error
		if isContainer(root) {
			if !isCompatibleContainer(root, value) {
				if _, isArr := root.([]interface{}); isArr {
					return nil, fmt.Errorf("failed to merge statements: cannot merge array with non-array")
				}
				return nil, fmt.Errorf("failed to merge statements: cannot merge object with non-object")
			}
			// Compatible: if value is empty container of same type, keep root
			if isEmptyContainer(value) {
				return root, nil
			}
			return value, nil
		}
		return value, nil
	}
	key := path[0]
	rest := path[1:]
	switch k := key.(type) {
	case int:
		var arr []interface{}
		if root == nil {
			arr = []interface{}{}
		} else {
			var ok bool
			arr, ok = root.([]interface{})
			if !ok {
				return nil, fmt.Errorf("failed to merge statements: cannot merge array with non-array")
			}
		}
		for len(arr) <= k {
			arr = append(arr, nil)
		}
		nested, err := mergeInto(arr[k], rest, value)
		if err != nil {
			return nil, err
		}
		arr[k] = nested
		return arr, nil
	case string:
		var obj map[string]interface{}
		if root == nil {
			obj = map[string]interface{}{}
		} else {
			var ok bool
			obj, ok = root.(map[string]interface{})
			if !ok {
				return nil, fmt.Errorf("failed to merge statements: cannot merge object with non-object")
			}
		}
		nested, err := mergeInto(obj[k], rest, value)
		if err != nil {
			return nil, err
		}
		obj[k] = nested
		return obj, nil
	}
	return root, nil
}

func isContainer(v interface{}) bool {
	switch v.(type) {
	case map[string]interface{}, []interface{}:
		return true
	}
	return false
}

func isEmptyContainer(v interface{}) bool {
	switch c := v.(type) {
	case map[string]interface{}:
		return len(c) == 0
	case []interface{}:
		return len(c) == 0
	}
	return false
}

func isCompatibleContainer(a, b interface{}) bool {
	_, am := a.(map[string]interface{})
	_, bm := b.(map[string]interface{})
	if am && bm {
		return true
	}
	_, aa := a.([]interface{})
	_, ba := b.([]interface{})
	if aa && ba {
		return true
	}
	return false
}
