			}
			return value, nil
		}
		return value, nil
	}
	key := path[0]
	rest := path[1:]
	switch k := key.(type) {
	case int:
		var arr []interface{}
		if root == nil {
			arr = []interface{}{}
		} else {
			var ok bool
			arr, ok = root.([]interface{})
			if !ok {
				return nil, fmt.Errorf("failed to merge statements: cannot merge array with non-array")
			}
