		if err != nil {
			return nil, err
		}
		obj[k] = nested
		return obj, nil
	}
	return root, nil
}

func isContainer(v interface{}) bool {
	switch v.(type) {
	case map[string]interface{}, []interface{}:
		return true
	}
	return false
}

func isEmptyContainer(v interface{}) bool {
	switch c := v.(type) {
	case map[string]interface{}:
		return len(c) == 0
	case []interface{}:
		return len(c) == 0
	}
	return false
}

