		if t.typ == TypeEquals {
			eqIdx = i
			break
		}
	}
	if eqIdx == -1 {
		// No equals sign at all
		return nil, nil, fmt.Errorf("ungron failed for `%s`: invalid statement", line)
	}

	pathToks := tokens[:eqIdx]
	valToks := tokens[eqIdx+1:]

	path, err := pathTokensToPath(pathToks)
	if err != nil {
		return nil, nil, fmt.Errorf("ungron failed for `%s`: %s", line, err.Error())
	}

	// Value must be followed by a ; (semicolon)
	if len(valToks) == 0 {
		return nil, nil, fmt.Errorf("ungron failed for `%s`: statement has no value", l.errorPrefix())
	}

	// Look for the semicolon and value
	// Acceptable patterns: <value><;> or <{><}><;> or <[><]><;>
	value, err := parseValue(valToks, l.errorPrefix())
	if err != nil {
		return nil, nil, err
	}
	return path, value, nil
}

// parseValue parses a value token sequence. Expects `value;` or `{}<;>` or `[]<;>`.
func parseValue(toks []token, prefix string) (interface{}, error) {
	// Find where the value ends (before ;)
	// Simplest: require first token is a value, next is ;
	i := 0
	// Skip leading whitespace? Not needed — already handled by lexer.
	if i >= len(toks) {
		return nil, fmt.Errorf("ungron failed for `%s`: statement has no value", prefix)
	}
	t := toks[i]
	var val interface{}
	var hasValue bool
	switch t.typ {
	case TypeNumber:
		val = json.Number(t.text)
		hasValue = true
		i++
	case TypeString:
		var s string
		if err := json.Unmarshal([]byte(t.text), &s); err != nil {
			return nil, fmt.Errorf("ungron failed for `%s`: invalid value `%s`", prefix, t.text)
		}
		val = s
		hasValue = true
		i++
	case TypeBool:
		val = t.text == "true"
		hasValue = true
		i++
	case TypeNull:
		val = nil
		hasValue = true
		i++
	case TypeLBrace:
		if i+1 < len(toks) && toks[i+1].typ == TypeRBrace {
			val = map[string]interface{}{}
			hasValue = true
			i += 2
		}
	case TypeLBracket:
		if i+1 < len(toks) && toks[i+1].typ == TypeRBracket {
			val = []interface{}{}
			hasValue = true
			i += 2
		}
	case TypeSemi:
		return nil, fmt.Errorf("ungron failed for `%s`: invalid value ``", prefix)
	}

	if !hasValue {
		return nil, fmt.Errorf("ungron failed for `%s`: statement has no value", prefix)
	}

	// Require a trailing semicolon
	if i >= len(toks) || toks[i].typ != TypeSemi {
		return nil, fmt.Errorf("ungron failed for `%s`: statement has no value", prefix)
	}
	return val, nil
}

// parseJSONLine parses a JSON stream line `[path_array, value]`.
func parseJSONLine(line string) ([]interface{}, interface{}, error) {
	var arr []interface{}
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	if err := dec.Decode(&arr); err != nil {
		return nil, nil, err
	}
	if len(arr) != 2 {
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	pathRaw, ok := arr[0].([]interface{})
	if !ok {
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	path := make([]interface{}, 0, len(pathRaw))
	for _, p := range pathRaw {
		switch pv := p.(type) {
		case string:
			path = append(path, pv)
		case json.Number:
			n, err := pv.Int64()
			if err != nil {
				return nil, nil, fmt.Errorf("invalid JSON layout")
			}
			path = append(path, int(n))
		default:
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	}
	value := arr[1]
	switch v := value.(type) {
	case nil, bool, string, json.Number:
	case map[string]interface{}:
		if len(v) != 0 {
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	case []interface{}:
		if len(v) != 0 {
			return nil, nil, fmt.Errorf("invalid JSON layout")
		}
	default:
		return nil, nil, fmt.Errorf("invalid JSON layout")
	}
	return path, value, nil
}

// pathTokensToPath converts a sequence of path tokens to a slice of keys/indices
func pathTokensToPath(toks []token) ([]interface{}, error) {
	var result []interface{}
	i := 0
	for i < len(toks) {
		t := toks[i]
		switch t.typ {
		case TypeBare:
			result = append(result, t.text)
			i++
		case TypeDot:
			i++
			if i >= len(toks) || toks[i].typ != TypeBare {
				return nil, fmt.Errorf("invalid statement")
			}
			result = append(result, toks[i].text)
			i++
		case TypeLBracket:
			i++
			if i >= len(toks) {
				return nil, fmt.Errorf("invalid statement")
			}
			switch toks[i].typ {
			case TypeNumber:
				n, err := strconv.Atoi(toks[i].text)
				if err != nil {
					return nil, fmt.Errorf("invalid statement")
				}
				result = append(result, n)
			case TypeQuotedKey:
				var s string
				if err := json.Unmarshal([]byte(toks[i].text), &s); err != nil {
					return nil, fmt.Errorf("invalid statement")
				}
				result = append(result, s)
			default:
				return nil, fmt.Errorf("invalid statement")
			}
			i++
			if i >= len(toks) || toks[i].typ != TypeRBracket {
				return nil, fmt.Errorf("invalid statement")
			}
			i++
		default:
			return nil, fmt.Errorf("invalid statement")
		}
	}
	return result, nil
}

// encodeJSON pretty-prints the value as JSON
func encodeJSON(v interface{}, colorize bool) (string, error) {
	if colorize {
		return encodeJSONColor(v)
	}
	var sb strings.Builder
	enc := json.NewEncoder(&sb)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return "", err
	}
	return strings.TrimRight(sb.String(), "\n"), nil
}

// encodeJSONColor produces colored JSON (compressed)
func encodeJSONColor(v interface{}) (string, error) {
	var sb strings.Builder
	err := writeColorValue(&sb, v)
	return sb.String(), err
}

func writeColorValue(sb *strings.Builder, v interface{}) error {
	switch val := v.(type) {
	case map[string]interface{}:
		sb.WriteString("\033[35m{\033[0m")
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		for i := 1; i < len(keys); i++ {
			for j := i; j > 0 && keys[j-1] > keys[j]; j-- {
				keys[j-1], keys[j] = keys[j], keys[j-1]
			}
		}
		for i, k := range keys {
			if i > 0 {
				sb.WriteString("\033[1m,\033[22m")
			}
			sb.WriteString("\033[34;1m\"\033[0;22m")
			sb.WriteString("\033[34;1m")
			writeEscapedStringInner(sb, k)
			sb.WriteString("\033[0;22m")
			sb.WriteString("\033[34;1m\"\033[0;22m")
			sb.WriteString("\033[1m:\033[22m")
			if err := writeColorValue(sb, val[k]); err != nil {
				return err
			}
		}
		sb.WriteString("\033[35m}\033[0m")
	case []interface{}:
		sb.WriteString("\033[35m[\033[0m")
		for i, item := range val {
			if i > 0 {
				sb.WriteString("\033[1m,\033[22m")
			}
			if err := writeColorValue(sb, item); err != nil {
				return err
			}
		}
		sb.WriteString("\033[35m]\033[0m")
	case nil:
		sb.WriteString("\033[36mnull\033[0m")
	case bool:
		if val {
			sb.WriteString("\033[36mtrue\033[0m")
		} else {
			sb.WriteString("\033[36mfalse\033[0m")
		}
	case json.Number:
		sb.WriteString("\033[31m")
		sb.WriteString(string(val))
		sb.WriteString("\033[0m")
	case string:
		sb.WriteString("\033[32m\"\033[0m")
		sb.WriteString("\033[33m")
		writeEscapedStringInner(sb, val)
		sb.WriteString("\033[0m")
		sb.WriteString("\033[32m\"\033[0m")
	default:
		b, err := json.Marshal(v)
		if err != nil {
			return err
		}
		sb.WriteString(string(b))
	}
	return nil
}

func writeEscapedStringInner(sb *strings.Builder, s string) {
	encoded := encodeString(s)
	if len(encoded) >= 2 {
		sb.WriteString(encoded[1 : len(encoded)-1])
	}
}

// --- Lexer ---

type lexer struct {
	input string
	pos   int
}

func newLexer(s string) *lexer {
	return &lexer{input: s}
}

func (l *lexer) errorPrefix() string {
	return strings.TrimRight(l.input[:l.pos], " \t")
}

// lexStatement lexes the line into tokens
func (l *lexer) lexStatement() ([]token, error) {
	var tokens []token
	seenEquals := false
	afterEquals := false
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if !seenEquals {
			if c == ' ' || c == '\t' {
				l.pos++
				continue
			}
			if c == '.' {
				tokens = append(tokens, token{TypeDot, "."})
				l.pos++
				ident, err := l.lexIdent()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeBare, ident})
				continue
			}
			if c == '[' {
				tokens = append(tokens, token{TypeLBracket, "["})
				l.pos++
				if l.pos >= len(l.input) {
					return nil, fmt.Errorf("invalid statement")
				}
				nc := l.input[l.pos]
				if nc == '"' {
					q, err := l.lexQuoted()
					if err != nil {
						return nil, err
					}
					tokens = append(tokens, token{TypeQuotedKey, q})
				} else if nc == '-' || (nc >= '0' && nc <= '9') {
					n, err := l.lexNumber()
					if err != nil {
						return nil, err
					}
					tokens = append(tokens, token{TypeNumber, n})
				} else {
					return nil, fmt.Errorf("invalid statement")
				}
				if l.pos >= len(l.input) || l.input[l.pos] != ']' {
					return nil, fmt.Errorf("invalid statement")
				}
				tokens = append(tokens, token{TypeRBracket, "]"})
				l.pos++
				continue
			}
			if c == '=' {
				tokens = append(tokens, token{TypeEquals, "="})
				l.pos++
				seenEquals = true
				afterEquals = true
				continue
			}
			if isIdentStart(rune(c)) {
				ident, err := l.lexIdent()
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token{TypeBare, ident})
				continue
			}
			return nil, fmt.Errorf("invalid statement")
		}
		// afterEquals
		if c == ' ' || c == '\t' {
			l.pos++
			continue
		}
		if c == '"' {
			q, err := l.lexQuoted()
			if err != nil {
				return nil, err
			}
			tokens = append(tokens, token{TypeString, q})
			afterEquals = false
			continue
		}
		if c == '-' || (c >= '0' && c <= '9') {
			n, err := l.lexNumber()
			if err != nil {
				return nil, err
			}
			tokens = append(tokens, token{TypeNumber, n})
			afterEquals = false
			continue
		}
		if c == '{' {
			tokens = append(tokens, token{TypeLBrace, "{"})
			l.pos++
			// expect }
			for l.pos < len(l.input) && (l.input[l.pos] == ' ' || l.input[l.pos] == '\t') {
				l.pos++
			}
			if l.pos < len(l.input) && l.input[l.pos] == '}' {
				tokens = append(tokens, token{TypeRBrace, "}"})
				l.pos++
				afterEquals = false
				continue
			}
			return nil, fmt.Errorf("statement has no value")
		}
		if c == '[' {
			tokens = append(tokens, token{TypeLBracket, "["})
			l.pos++
			for l.pos < len(l.input) && (l.input[l.pos] == ' ' || l.input[l.pos] == '\t') {
				l.pos++
			}
			if l.pos < len(l.input) && l.input[l.pos] == ']' {
				tokens = append(tokens, token{TypeRBracket, "]"})
				l.pos++
				afterEquals = false
				continue
			}
			return nil, fmt.Errorf("statement has no value")
		}
		if strings.HasPrefix(l.input[l.pos:], "true") {
			tokens = append(tokens, token{TypeBool, "true"})
			l.pos += 4
			afterEquals = false
			continue
		}
		if strings.HasPrefix(l.input[l.pos:], "false") {
			tokens = append(tokens, token{TypeBool, "false"})
			l.pos += 5
			afterEquals = false
			continue
		}
		if strings.HasPrefix(l.input[l.pos:], "null") {
			tokens = append(tokens, token{TypeNull, "null"})
			l.pos += 4
			afterEquals = false
			continue
		}
		if c == ';' {
			// Empty value — produce a Semi token and let upper layer error
			tokens = append(tokens, token{TypeSemi, ";"})
			l.pos++
			return tokens, nil
		}
		return nil, fmt.Errorf("invalid value `%c`", c)
	}
	// Reached end of input
	// After value, consume trailing whitespace and `;` if present
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if c == ' ' || c == '\t' {
			l.pos++
			continue
		}
		if c == ';' {
			tokens = append(tokens, token{TypeSemi, ";"})
			l.pos++
			break
		}
		break
	}
	// Append semi if we saw one
	// Look at last tokens to see if we need to add ;
	// Actually, we process each encountered ; - if at end, we return.
	return tokens, nil
}

func (l *lexer) lexIdent() (string, error) {
	start := l.pos
	if l.pos >= len(l.input) {
		return "", fmt.Errorf("invalid statement")
	}
	r, size := utf8.DecodeRuneInString(l.input[l.pos:])
	if !isIdentStart(r) {
		return "", fmt.Errorf("invalid statement")
	}
	l.pos += size
	for l.pos < len(l.input) {
		r, size := utf8.DecodeRuneInString(l.input[l.pos:])
		if !isIdentPart(r) {
			break
		}
		l.pos += size
	}
	return l.input[start:l.pos], nil
}

func isIdentStart(r rune) bool {
	return unicode.IsLetter(r) || r == '$' || r == '_'
}

func isIdentPart(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '$' || r == '_'
}

func (l *lexer) lexQuoted() (string, error) {
	start := l.pos
	if l.pos >= len(l.input) || l.input[l.pos] != '"' {
		return "", fmt.Errorf("invalid statement")
	}
	l.pos++
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if c == '"' {
			l.pos++
			return l.input[start:l.pos], nil
		}
		if c == '\\' {
			l.pos++
			if l.pos >= len(l.input) {
				return "", fmt.Errorf("invalid statement")
			}
			l.pos++
			continue
		}
		l.pos++
	}
	return "", fmt.Errorf("invalid statement")
}

func (l *lexer) lexNumber() (string, error) {
	start := l.pos
	if l.pos < len(l.input) && l.input[l.pos] == '-' {
		l.pos++
	}
	hasDigit := false
	for l.pos < len(l.input) {
		c := l.input[l.pos]
		if c >= '0' && c <= '9' {
			l.pos++
			hasDigit = true
			continue
		}
		break
	}
	if l.pos < len(l.input) && l.input[l.pos] == '.' {
		l.pos++
		for l.pos < len(l.input) {
			c := l.input[l.pos]
			if c >= '0' && c <= '9' {
				l.pos++
				hasDigit = true
				continue
			}
			break
		}
	}
	if l.pos < len(l.input) && (l.input[l.pos] == 'e' || l.input[l.pos] == 'E') {
		l.pos++
		if l.pos < len(l.input) && (l.input[l.pos] == '+' || l.input[l.pos] == '-') {
			l.pos++
		}
		for l.pos < len(l.input) {
			c := l.input[l.pos]
			if c >= '0' && c <= '9' {
				l.pos++
				continue
			}
			break
		}
	}
	if !hasDigit {
		return "", fmt.Errorf("invalid statement")
	}
	return l.input[start:l.pos], nil
}

// --- Values extraction ---

func extractValue(line string) (string, bool, error) {
	l := newLexer(line)
	tokens, err := l.lexStatement()
	if err != nil {
		if strings.TrimSpace(line) == "" {
			return "", false, fmt.Errorf("failed to parse '%s' as gron statement", line)
		}
		return "", false, nil
	}
	eqIdx := -1
	for i, t := range tokens {
		if t.typ == TypeEquals {
			eqIdx = i
			break
		}
	}
	if eqIdx == -1 {
		return "", false, nil
	}
	valToks := tokens[eqIdx+1:]
	if len(valToks) == 0 {
		return "", true, nil
	}
	t := valToks[0]
	switch t.typ {
	case TypeString:
		var s string
		if err := json.Unmarshal([]byte(t.text), &s); err != nil {
			return t.text, true, nil
		}
		return s, true, nil
	case TypeNumber, TypeBool, TypeNull:
		return t.text, true, nil
	case TypeLBrace, TypeLBracket:
		return "", false, nil
	case TypeSemi:
		return "", true, nil
	default:
		return t.text, true, nil
	}
}
